from datetime import datetime, timedelta, date
import re


def next_run(expression: str, after: datetime) -> datetime | None:
    parts = re.split(r'[ \t]+', expression.strip())
    if len(parts) != 5:
        raise ValueError(f"Expected 5 fields, got {len(parts)}")

    _MONTH_NAMES = {
        'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
        'JUL': 7, 'AUG': 8, 'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12
    }
    _WEEKDAY_NAMES = {
        'SUN': 0, 'MON': 1, 'TUE': 2, 'WED': 3, 'THU': 4, 'FRI': 5, 'SAT': 6
    }

    minutes = _parse_field(parts[0], 0, 59, None)
    hours = _parse_field(parts[1], 0, 23, None)
    doms = _parse_field(parts[2], 1, 31, None)
    months = _parse_field(parts[3], 1, 12, _MONTH_NAMES)
    dows = _parse_field(parts[4], 0, 7, _WEEKDAY_NAMES)

    if 7 in dows:
        dows.discard(7)
        dows.add(0)

    dom_unspec = (parts[2] == '*')
    dow_unspec = (parts[4] == '*')

    sorted_hours = sorted(hours)
    sorted_minutes = sorted(minutes)

    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    max_year = after.year + 10

    cur = date(start.year, start.month, start.day)
    first_day = True

    for _ in range(3700):
        if cur.year > max_year:
            return None

        if cur.month in months:
            cron_dow = (cur.weekday() + 1) % 7

            if not dom_unspec and not dow_unspec:
                day_ok = (cur.day in doms) or (cron_dow in dows)
            elif not dom_unspec:
                day_ok = cur.day in doms
            elif not dow_unspec:
                day_ok = cron_dow in dows
            else:
                day_ok = True

            if day_ok:
                if first_day:
                    t = _find_earliest(sorted_hours, sorted_minutes, start.hour, start.minute)
                else:
                    t = _find_earliest(sorted_hours, sorted_minutes, 0, 0)
                if t is not None:
                    h, mi = t
                    result = datetime(cur.year, cur.month, cur.day, h, mi)
                    if result.year > max_year:
                        return None
                    return result

        cur += timedelta(days=1)
        first_day = False

    return None


def _find_earliest(sorted_hours, sorted_minutes, min_h, min_m):
    for h in sorted_hours:
        if h < min_h:
            continue
        if h == min_h:
            for m in sorted_minutes:
                if m >= min_m:
                    return (h, m)
        else:
            return (h, sorted_minutes[0])
    return None


def _parse_field(field, lo, hi, names):
    result = set()
    items = field.split(',')
    for item in items:
        if item == '':
            raise ValueError(f"Empty item in field '{field}'")
        if item == '*':
            for v in range(lo, hi + 1):
                result.add(v)
        elif item.startswith('*/'):
            n = _parse_step(item[2:])
            for v in range(lo, hi + 1, n):
                result.add(v)
        elif '-' in item:
            slash_parts = item.split('/')
            if len(slash_parts) > 2:
                raise ValueError(f"Invalid item: '{item}'")
            range_str = slash_parts[0]
            dash_parts = range_str.split('-')
            if len(dash_parts) != 2:
                raise ValueError(f"Invalid range: '{range_str}'")
            a = _parse_value(dash_parts[0], lo, hi, names)
            b = _parse_value(dash_parts[1], lo, hi, names)
            if a > b:
                raise ValueError(f"Range start {a} > end {b}")
            if len(slash_parts) == 2:
                n = _parse_step(slash_parts[1])
                for v in range(a, b + 1, n):
                    result.add(v)
            else:
                for v in range(a, b + 1):
                    result.add(v)
        else:
            if '/' in item:
                raise ValueError(f"Step without range not allowed: '{item}'")
            v = _parse_value(item, lo, hi, names)
            result.add(v)
    return result


def _parse_value(s, lo, hi, names):
    if names is not None:
        upper = s.upper()
        if upper in names:
            return names[upper]
    if not s or any(c not in '0123456789' for c in s):
        raise ValueError(f"Invalid value: '{s}'")
    val = int(s)
    if val < lo or val > hi:
        raise ValueError(f"Value {val} out of range [{lo}, {hi}]")
    return val


def _parse_step(s):
    if not s or any(c not in '0123456789' for c in s):
        raise ValueError(f"Invalid step: '{s}'")
    n = int(s)
    if n < 1:
        raise ValueError(f"Step must be >= 1, got {n}")
    return n
